package dev.starcrownqa;
import dev.starcrown.*;
import net.minecraft.gametest.framework.*;
import net.minecraftforge.gametest.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.entity.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.effect.*;
import net.minecraft.core.BlockPos;
@GameTestHolder("starcrownqa") @PrefixGameTestTemplate(false)
public final class SevenTests {
 private static ServerPlayer player(GameTestHelper h){var l=h.getLevel();var p=new ServerPlayer(l.getServer(),l,new com.mojang.authlib.GameProfile(java.util.UUID.randomUUID(),"seven-test"));var c=new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND);new io.netty.channel.embedded.EmbeddedChannel(c);c.setProtocol(net.minecraft.network.ConnectionProtocol.PLAY);p.connection=new net.minecraft.server.network.ServerGamePacketListenerImpl(l.getServer(),c,p);p.moveTo(h.absolutePos(new BlockPos(2,3,2)),0,0);l.addNewPlayer(p);p.setItemSlot(EquipmentSlot.HEAD,new ItemStack(StarcrownDoll.ITEM.get()));DivineAnchor.observe(p);return p;}
 private static void cleanup(ServerPlayer p){DivineSeven.settings(p).putBoolean("domain",false);DivineAnchor.unlock(p);p.setItemSlot(EquipmentSlot.HEAD,ItemStack.EMPTY);DivineWill.update(p,false);p.serverLevel().removePlayerImmediately(p,Entity.RemovalReason.DISCARDED);p.connection.connection.disconnect(net.minecraft.network.chat.Component.literal("done"));}
 @GameTest(template="empty",timeoutTicks=100) public static void willAndRelease(GameTestHelper h){var p=player(h);try{p.tickCount=20;p.addEffect(new MobEffectInstance(MobEffects.POISON,200));DivineSeven.settings(p).putInt("speed",4);DivineWill.update(p,true);h.assertTrue(p.getAbilities().mayfly&&p.hasEffect(MobEffects.LUCK)&&p.hasEffect(MobEffects.NIGHT_VISION),"flight and registry beneficial effects granted");p.getAbilities().mayfly=false;p.getAbilities().setFlyingSpeed(0);p.tickCount=21;DivineWill.update(p,true);h.assertTrue(p.getAbilities().mayfly&&p.getAbilities().getFlyingSpeed()>0,"flight permission restored after overwrite");p.getAbilities().flying=true;DivineWill.update(p,true);h.assertTrue(p.getAbilities().flying,"active flight retained during refresh");h.assertTrue(p.hasEffect(CombatQa.FUTURE.get())&&!p.hasEffect(MobEffects.POISON)&&p.getFoodData().getFoodLevel()==20,"negative effect rejected and hunger safe");h.assertTrue(p.getAttributeValue(net.minecraftforge.common.ForgeMod.BLOCK_REACH.get())>=20,"reach increased by sixteen");DivineWill.update(p,false);h.assertTrue(!p.hasEffect(MobEffects.LUCK)&&!p.getAbilities().mayfly,"owned effects and survival flight released");h.succeed();}finally{cleanup(p);}}
 @GameTest(template="empty",timeoutTicks=100) public static void aiSphereAndFriends(GameTestHelper h){var p=player(h);var a=EntityType.ZOMBIE.create(h.getLevel());var b=EntityType.COW.create(h.getLevel());try{a.moveTo(p.getX()+11.5,p.getY(),p.getZ());b.moveTo(p.getX()+5,p.getY(),p.getZ());h.getLevel().addFreshEntity(a);h.getLevel().addFreshEntity(b);h.assertTrue(DivineEternity.sealed(a),"AI paused inside twelve-block sphere");a.moveTo(p.getX()+9,p.getY()+9,p.getZ());h.assertTrue(!DivineEternity.sealed(a),"sphere excludes diagonal outside radius");var friends=new net.minecraft.nbt.CompoundTag();friends.putBoolean(b.getUUID().toString(),true);DivineSeven.settings(p).put("friends",friends);h.assertTrue(!DivineEternity.sealed(b),"friend AI excluded");h.succeed();}finally{cleanup(p);a.discard();b.discard();}}
 @GameTest(template="empty",timeoutTicks=100) public static void domainAndVerdict(GameTestHelper h){var p=player(h);var enemy=EntityType.RAVAGER.create(h.getLevel());try{enemy.moveTo(p.position());h.getLevel().addFreshEntity(enemy);DivineSeven.settings(p).putBoolean("domain",true);h.assertTrue(DivineSeven.ruled(enemy),"hostile ruled by domain");var before=enemy.position();enemy.teleportTo(before.x+8,before.y,before.z);h.assertTrue(enemy.position().equals(before),"direct entity teleport blocked");enemy.setHealth(50);enemy.heal(30);h.assertTrue(enemy.getHealth()<=50,"domain healing denied");DivineSeven.settings(p).putBoolean("domain",false);DivineSeven.attacked(new net.minecraftforge.event.entity.living.LivingAttackEvent(p,p.damageSources().mobAttack(enemy),1));h.assertTrue(DivineSeven.owner(enemy)==p,"attacker marked even against protected wearer");for(int i=0;i<4&&enemy.isAlive();i++){enemy.invulnerableTime=0;enemy.hurt(p.damageSources().playerAttack(p),1);}h.assertTrue(enemy.getHealth()<=0,"four strikes execute marked target");enemy.setHealth(20);h.assertTrue(enemy.getHealth()==0,"defeated target cannot setHealth to revive");h.succeed();}finally{cleanup(p);enemy.discard();}}
 @GameTest(template="empty",timeoutTicks=100) public static void allyTotem(GameTestHelper h){var p=player(h);var cow=EntityType.COW.create(h.getLevel());try{cow.moveTo(p.getX()+3,p.getY(),p.getZ());h.getLevel().addFreshEntity(cow);var friends=new net.minecraft.nbt.CompoundTag();friends.putBoolean(cow.getUUID().toString(),true);DivineSeven.settings(p).put("friends",friends);cow.hurt(cow.damageSources().genericKill(),10000);h.assertTrue(cow.isAlive()&&!cow.isRemoved()&&cow.getHealth()>0,"ally rescued from lethal hit without a totem");cow.kill();h.assertTrue(cow.isAlive(),"direct kill also triggers rescue");h.assertTrue(cow.hasEffect(MobEffects.REGENERATION),"totem buffs granted");cow.moveTo(p.getX()+65,p.getY(),p.getZ());h.assertTrue(!DivineSeven.rescue(cow),"rescue strictly limited to sixty-four blocks");h.succeed();}finally{cleanup(p);cow.discard();}}
 @GameTest(template="empty",timeoutTicks=100) public static void historyRestore(GameTestHelper h){var p=player(h);try{var pos=p.blockPosition().offset(4,-1,0);var l=h.getLevel();l.setBlock(pos,Blocks.STONE.defaultBlockState(),3);DivineHistory.get(l).capture(p,pos);l.setBlock(pos,Blocks.AIR.defaultBlockState(),3);h.assertTrue(DivineHistory.preview(p)>=1,"journal has restorable battle state");h.assertTrue(DivineHistory.restore(p)>=1&&l.getBlockState(pos).is(Blocks.STONE),"terrain restored from journal");var chest=pos.above();l.setBlock(chest,Blocks.CHEST.defaultBlockState(),3);DivineHistory.get(l).capture(p,chest);l.setBlock(chest,Blocks.AIR.defaultBlockState(),3);DivineHistory.restore(p);h.assertTrue(l.getBlockState(chest).isAir(),"container content never snapshotted");h.succeed();}finally{cleanup(p);}}
 @GameTest(template="empty",timeoutTicks=100) public static void safeAnchors(GameTestHelper h){var p=player(h);try{var l=h.getLevel();var base=p.blockPosition().below();for(int x=-3;x<=3;x++)for(int z=-3;z<=3;z++)l.setBlock(base.offset(x,0,z),Blocks.STONE.defaultBlockState(),3);h.assertTrue(DivineTravel.save(p,0),"safe anchor stored");var before=p.position();p.moveTo(p.getX()+2,p.getY(),p.getZ());h.assertTrue(DivineTravel.anchor(p,0)&&p.position().distanceToSqr(before)<.01,"anchor returns to recorded spot");l.setBlock(p.blockPosition(),Blocks.LAVA.defaultBlockState(),3);h.assertTrue(!DivineTravel.safe(p,l,p.position()),"lava rejected");h.succeed();}finally{cleanup(p);}}
 @GameTest(template="empty",timeoutTicks=100) public static void domainProjectilesAndRelease(GameTestHelper h){var p=player(h);var zombie=EntityType.ZOMBIE.create(h.getLevel());try{zombie.moveTo(p.getX()+4,p.getY(),p.getZ());h.getLevel().addFreshEntity(zombie);DivineSeven.settings(p).putBoolean("domain",true);var arrow=new net.minecraft.world.entity.projectile.Arrow(h.getLevel(),zombie);arrow.moveTo(p.getX()+4,p.getY()+1,p.getZ());h.getLevel().addFreshEntity(arrow);p.tickCount=5;DivineSeven.tick(new net.minecraftforge.event.TickEvent.PlayerTickEvent(net.minecraftforge.event.TickEvent.Phase.END,p));h.assertTrue(arrow.isRemoved(),"enemy projectile removed by domain");var spawn=EntityType.ZOMBIE.create(h.getLevel());spawn.moveTo(p.getX()+6,p.getY(),p.getZ());h.assertTrue(!h.getLevel().addFreshEntity(spawn),"fresh hostile summon/spawn prevented");DivineAnchor.unlock(p);p.setItemSlot(EquipmentSlot.HEAD,ItemStack.EMPTY);DivineSeven.action(p,0,0);h.assertTrue(DivineSeven.settings(p).getBoolean("domain"),"unequipped player cannot issue ability actions");h.succeed();}finally{cleanup(p);zombie.discard();}}
 @GameTest(template="empty",timeoutTicks=100) public static void registryEffectRestoration(GameTestHelper h){var p=player(h);try{p.addEffect(new MobEffectInstance(MobEffects.LUCK,1200,2));float flight=p.getAbilities().getFlyingSpeed();DivineSeven.settings(p).putInt("speed",4);p.tickCount=20;DivineWill.update(p,true);h.assertTrue(Math.abs(p.getAbilities().getFlyingSpeed()-.25)<.0001,"flight speed follows selected multiplier");h.assertTrue(p.hasEffect(CombatQa.FUTURE.get()),"third-party registry benefit automatically granted");DivineWill.update(p,false);h.assertTrue(p.getEffect(MobEffects.LUCK).getAmplifier()==2,"external stronger benefit preserved on release");h.assertTrue(!p.hasEffect(CombatQa.FUTURE.get()),"owned third-party benefit released");h.assertTrue(Math.abs(p.getAbilities().getFlyingSpeed()-flight)<.0001,"previous flight speed restored");h.succeed();}finally{cleanup(p);}}
 @GameTest(template="empty",timeoutTicks=100) public static void recordedDamageAndRepayment(GameTestHelper h){var p=player(h);var enemy=EntityType.RAVAGER.create(h.getLevel());try{enemy.moveTo(p.getX(),p.getY(),p.getZ()+3);h.getLevel().addFreshEntity(enemy);enemy.hurt(p.damageSources().playerAttack(p),5);float low=enemy.getHealth();enemy.setHealth(enemy.getMaxHealth());h.assertTrue(enemy.getHealth()>low,"unprovoked target not given retaliation healing suppression");h.assertTrue(DivineSeven.aimed(p)==enemy,"server resolves aimed target");DivineSeven.action(p,13,0);h.assertTrue(enemy.getHealth()<=low,"old wound pulls target to recorded minimum");enemy.invulnerableTime=0;h.assertTrue(enemy.hasEffect(DivineEffects.COST.get()),"Cost applied automatically");float previous=enemy.getHealth();enemy.hurt(p.damageSources().generic(),1);h.assertTrue(Math.abs(previous-enemy.getHealth()-1)<.01,"ordinary incoming damage is no longer multiplied");h.succeed();}finally{cleanup(p);enemy.discard();}}
 @GameTest(template="empty",timeoutTicks=100) public static void creativeUnequipCleanup(GameTestHelper h){var p=player(h);try{p.setGameMode(net.minecraft.world.level.GameType.CREATIVE);p.tickCount=20;DivineWill.update(p,true);DivineAnchor.lock(p);DivineSeven.settings(p).putBoolean("domain",true);DivineSeven.settings(p).putBoolean("restoring",true);p.connection.handleSetCreativeModeSlot(new net.minecraft.network.protocol.game.ServerboundSetCreativeModeSlotPacket(5,ItemStack.EMPTY));DivineAnchor.repair(p);h.assertTrue(p.getItemBySlot(EquipmentSlot.HEAD).isEmpty()&&!DivineProtection.active(p)&&!DivineAnchor.locked(p),"creative head removal is not mistaken for hostile deletion");DivineWill.update(p,DivineWill.wearing(p));h.assertTrue(!p.hasEffect(MobEffects.LUCK)&&!DivineSeven.settings(p).getBoolean("domain")&&!DivineSeven.settings(p).getBoolean("restoring"),"unequip releases effects, domain and pending restoration");h.assertTrue(p.getAttributeValue(net.minecraftforge.common.ForgeMod.BLOCK_REACH.get())<10,"reach modifier removed");h.succeed();}finally{cleanup(p);}}
 @GameTest(template="empty",timeoutTicks=100) public static void excludedInvisibility(GameTestHelper h){var p=player(h);try{p.tickCount=20;DivineWill.update(p,true);h.assertTrue(!p.hasEffect(MobEffects.INVISIBILITY)&&p.hasEffect(MobEffects.LUCK),"invisibility excluded from automatic benefits");var saved=p.getPersistentData().getCompound("starcrowndoll_will_lease").getCompound("benefits");var before=new net.minecraft.nbt.CompoundTag();before.putLong("tick",p.serverLevel().getGameTime());saved.put("minecraft:invisibility",before);p.addEffect(new MobEffectInstance(MobEffects.INVISIBILITY,200,0,true,false,false));DivineWill.update(p,true);h.assertTrue(!p.hasEffect(MobEffects.INVISIBILITY),"legacy doll-owned invisibility removed");p.addEffect(new MobEffectInstance(MobEffects.INVISIBILITY,1200,0,false,true,true));DivineWill.update(p,true);h.assertTrue(p.hasEffect(MobEffects.INVISIBILITY),"external invisibility preserved");h.succeed();}finally{cleanup(p);}}
 @GameTest(template="empty",timeoutTicks=100) public static void dollAuthorityConfiscation(GameTestHelper h){var victim=player(h);var attacker=player(h);try{DivineAnchor.unlock(attacker);attacker.setItemSlot(EquipmentSlot.HEAD,new ItemStack(StarcrownDoll.YULE_ITEM.get()));attacker.getItemBySlot(EquipmentSlot.HEAD).getOrCreateTag().putString("owner_note","preserve");attacker.attack(victim);h.assertTrue(YuleHumility.active(attacker),"tolerance cancels attack before confiscation");DollAuthority.onAttack(attacker,victim);h.assertTrue(attacker.getItemBySlot(EquipmentSlot.HEAD).isEmpty()&&!YuleHumility.active(attacker),"shared authority handler confiscates exact doll");var list=victim.getPersistentData().getList("starcrown_confiscated_dolls",net.minecraft.nbt.Tag.TAG_COMPOUND);h.assertTrue(list.size()==1&&ItemStack.of(list.getCompound(0).getCompound("item")).getOrCreateTag().getString("owner_note").equals("preserve"),"confiscation preserves exact doll data");DivineSeven.action(victim,17,0);h.assertTrue(victim.getPersistentData().getList("starcrown_confiscated_dolls",net.minecraft.nbt.Tag.TAG_COMPOUND).isEmpty(),"confiscated item can be retrieved once");attacker.setItemSlot(EquipmentSlot.HEAD,new ItemStack(Items.STICK));h.assertTrue(DollAuthority.doll(attacker.getItemBySlot(EquipmentSlot.HEAD)),"future tag-based dolls use shared classification");attacker.attack(victim);h.assertTrue(attacker.getItemBySlot(EquipmentSlot.HEAD).isEmpty(),"future tagged doll also confiscated");h.succeed();}finally{cleanup(attacker);cleanup(victim);}}
}
